/**
 * Places dataset gate (roadmap P0 DoD, ADR-013): the committed seed payload
 * (data/places.json, generated by `npm run seed:places` from
 * nuhil/bangladesh-geocode + data/thana-overrides.json) must contain all
 * 8 divisions / 64 districts / 495 upazilas + the Chattogram metro thanas,
 * with EN+BN names, in-bounds coordinates and symmetric S-32 neighbours.
 * Also cross-checks places-notes.md checklist item 5: every upazila/thana
 * named in data/hospitals.csv exists verbatim in the seeded names.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { validatePlaces, type PlaceRow } from "../scripts/places-build";

const rows = JSON.parse(readFileSync("data/places.json", "utf8")) as PlaceRow[];
const byLevel = (lvl: PlaceRow["level"]) => rows.filter((r) => r.level === lvl);
const chattogram = rows.find((r) => r.level === "district" && r.nameEn === "Chattogram");

describe("places dataset", () => {
  it("passes structural validation (counts, bbox, parents, symmetry)", () => {
    expect(validatePlaces(rows)).toEqual([]);
  });

  it("has 8 divisions, 64 districts, 495 upazilas + Chattogram metro thanas", () => {
    expect(byLevel("division")).toHaveLength(8);
    expect(byLevel("district")).toHaveLength(64);
    expect(byLevel("upazila").filter((r) => !r.isMetroThana)).toHaveLength(495);
    const metro = byLevel("upazila").filter((r) => r.isMetroThana);
    expect(metro.length).toBeGreaterThanOrEqual(15);
    expect(metro.every((r) => r.parentCode === chattogram?.code)).toBe(true);
  });

  it("resolves all 16 Chattogram CCC thana names (15 seeded + Karnaphuli upazila)", () => {
    const ctgNames = new Set(
      byLevel("upazila").filter((r) => r.parentCode === chattogram?.code).map((r) => r.nameEn),
    );
    for (const name of [
      "Akbarshah", "Bakalia", "Bandar", "Bayezid", "Chandgaon", "Chawkbazar",
      "Double Mooring", "EPZ", "Halishahar", "Karnaphuli", "Khulshi", "Kotwali",
      "Pahartali", "Panchlaish", "Patenga", "Sadarghat",
    ]) {
      expect(ctgNames.has(name), `missing Chattogram thana ${name}`).toBe(true);
    }
  });

  it("every metro thana has at least one neighbour within S-32 (city density sanity)", () => {
    for (const r of byLevel("upazila").filter((x) => x.isMetroThana)) {
      expect(r.neighbourCodes.length, `${r.nameEn} has no neighbours`).toBeGreaterThan(0);
    }
  });

  it("every upazila/thana used by data/hospitals.csv exists in the seeded names", () => {
    const csv = readFileSync("data/hospitals.csv", "utf8").trim().split("\n").slice(1);
    const names = new Set(rows.map((r) => r.nameEn));
    const used = new Set(csv.map((line) => line.split(",")[5]?.trim()));
    for (const u of used) {
      if (u) expect(names.has(u), `hospitals.csv upazila "${u}" not in places`).toBe(true);
    }
    // The nine names from the places-notes checklist, explicitly:
    for (const name of ["Panchlaish", "Double Mooring", "Kotwali", "Sitakunda", "Hathazari", "Khulshi", "Bayezid", "Patenga", "Bandar"]) {
      expect(names.has(name)).toBe(true);
    }
  });

  it("places.min.json (offline picker bundle) matches the payload counts", () => {
    const min = JSON.parse(readFileSync("src/data/places.min.json", "utf8")) as unknown[];
    expect(min).toHaveLength(rows.length);
  });
});
